"use client";
// Adapted from shadcn/ui (MIT). Retain panels and make reversal interruptible.
import * as React from "react";
import { AutoHeight } from "@animate-ui/react/primitives/effects/auto-height";
import { Accordion as Primitive } from "./primitive-accordion";
import { ChevronDownIcon } from "lucide-react";
import { cn } from "./utils";
import "./accordion.css";
const Values = React.createContext<string[]>([]),
  ItemOpen = React.createContext(false);
function Accordion(props: React.ComponentProps<typeof Primitive.Root>) {
  const [internal, setInternal] = React.useState<string | string[]>(
    props.defaultValue ?? (props.type === "multiple" ? [] : ""),
  );
  const value = props.value === undefined ? internal : props.value;
  const change = (next: string | string[]) => {
    if (props.value === undefined) setInternal(next);
    if (props.type === "multiple") props.onValueChange?.(next as string[]);
    else props.onValueChange?.(next as string);
  };
  const root =
    props.type === "multiple" ? (
      <Primitive.Root
        {...props}
        value={value as string[]}
        onValueChange={change}
      />
    ) : (
      <Primitive.Root
        {...props}
        value={value as string}
        onValueChange={change}
      />
    );
  return (
    <Values.Provider value={Array.isArray(value) ? value : [value]}>
      {root}
    </Values.Provider>
  );
}
function AccordionItem({
  className,
  value,
  ...props
}: React.ComponentProps<typeof Primitive.Item>) {
  const open = React.useContext(Values).includes(value);
  return (
    <ItemOpen.Provider value={open}>
      <Primitive.Item
        {...props}
        value={value}
        data-slot="accordion-item"
        className={cn("roc-ui", className)}
      />
    </ItemOpen.Provider>
  );
}
function AccordionTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Header className="roc-ui-accordion-heading">
      <Primitive.Trigger
        {...props}
        data-slot="accordion-trigger"
        className={cn("roc-ui", className)}
      >
        {children}
        <ChevronDownIcon aria-hidden="true" className="roc-ui-icon" />
      </Primitive.Trigger>
    </Primitive.Header>
  );
}
function AccordionContent({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Primitive.Content>) {
  const open = React.useContext(ItemOpen);
  return (
    <Primitive.Content
      {...props}
      forceMount
      inert={!open}
      aria-hidden={!open}
      data-slot="accordion-content"
      className={cn("roc-ui", className)}
    >
      <AutoHeight className="roc-ui-accordion-layout" data-open={open} initial={false}
        animate={{ height: open ? "auto" : 0, opacity: open ? 1 : 0 }}>
        <div className="roc-ui-accordion-clip">
          <div className="roc-ui-accordion-body">{children}</div>
        </div>
      </AutoHeight>
    </Primitive.Content>
  );
}
export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

"use client";
// ROC primitive: a stack of headers that each reveal a panel.
import * as React from "react";
import { useDirectionContext } from "./primitive-direction-context";
import { composeEventHandlers, useComposedRefs } from "./primitive-utils";
import { ROVING_ROOT, handleRovingKey, type Orientation } from "./primitive-roving";

type Context = {
  disabled: boolean;
  orientation: Orientation;
  values: string[];
  open: (value: string) => void;
  close: (value: string) => void;
  collapsible: boolean;
};
const AccordionContext = React.createContext<Context | null>(null);
const ItemContext = React.createContext<{
  value: string;
  open: boolean;
  disabled: boolean;
  triggerId: string;
  contentId: string;
} | null>(null);
const useAccordion = () => {
  const context = React.useContext(AccordionContext);
  if (!context) throw new Error("Accordion parts must be inside Accordion.Root");
  return context;
};
const useItem = () => {
  const context = React.useContext(ItemContext);
  if (!context) throw new Error("Accordion parts must be inside Accordion.Item");
  return context;
};

type Shared = Omit<React.ComponentProps<"div">, "defaultValue" | "dir"> & {
  disabled?: boolean;
  orientation?: Orientation;
  dir?: "ltr" | "rtl";
};
type SingleProps = Shared & {
  type: "single";
  /** Allow the open item to be closed again. */
  collapsible?: boolean;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};
type MultipleProps = Shared & {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
};
type RootProps = SingleProps | MultipleProps;

const toArray = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value : value ? [value] : [];

function Root(props: RootProps) {
  const {
    type,
    value,
    defaultValue,
    onValueChange,
    disabled = false,
    orientation = "vertical",
    dir: dirProp,
    onKeyDown,
    ref,
    ...rest
  } = props as Shared & {
    type: "single" | "multiple";
    value?: string | string[];
    defaultValue?: string | string[];
    onValueChange?: (value: any) => void;
  };
  const dir = useDirectionContext(dirProp);
  const collapsible = type === "multiple" || !!(props as SingleProps).collapsible;
  delete (rest as { collapsible?: boolean }).collapsible;
  const [internal, setInternal] = React.useState(() => toArray(defaultValue));
  const values = value === undefined ? internal : toArray(value);
  const change = (next: string[]) => {
    if (value === undefined) setInternal(next);
    onValueChange?.(type === "multiple" ? next : (next[0] ?? ""));
  };
  const root = React.useRef<HTMLDivElement>(null);
  const composed = useComposedRefs<HTMLDivElement>(ref as React.Ref<HTMLDivElement>, root);
  return (
    <AccordionContext.Provider
      value={{
        disabled,
        orientation,
        values,
        collapsible,
        open: (item) => change(type === "multiple" ? [...values, item] : [item]),
        close: (item) =>
          change(values.filter((existing) => existing !== item)),
      }}
    >
      <div
        dir={dir}
        data-orientation={orientation}
        {...{ [ROVING_ROOT]: "" }}
        {...rest}
        ref={composed}
        onKeyDown={composeEventHandlers(onKeyDown, (event) =>
          handleRovingKey(event, root.current, { orientation, dir }),
        )}
      />
    </AccordionContext.Provider>
  );
}

function Item({
  value,
  disabled: itemDisabled,
  ...props
}: React.ComponentProps<"div"> & { value: string; disabled?: boolean }) {
  const accordion = useAccordion();
  const id = React.useId();
  const open = accordion.values.includes(value);
  const disabled = accordion.disabled || !!itemDisabled;
  return (
    <ItemContext.Provider
      value={{
        value,
        open,
        disabled,
        triggerId: `${id}-trigger`,
        contentId: `${id}-content`,
      }}
    >
      <div
        data-orientation={accordion.orientation}
        data-state={open ? "open" : "closed"}
        data-disabled={disabled ? "" : undefined}
        {...props}
      />
    </ItemContext.Provider>
  );
}

function Header(props: React.ComponentProps<"h3">) {
  const accordion = useAccordion();
  const item = useItem();
  return (
    <h3
      data-orientation={accordion.orientation}
      data-state={item.open ? "open" : "closed"}
      data-disabled={item.disabled ? "" : undefined}
      {...props}
    />
  );
}

function Trigger({ onClick, ...props }: React.ComponentProps<"button">) {
  const accordion = useAccordion();
  const item = useItem();
  return (
    <button
      type="button"
      aria-controls={item.contentId}
      aria-expanded={item.open}
      aria-disabled={(item.open && !accordion.collapsible) || undefined}
      data-orientation={accordion.orientation}
      data-state={item.open ? "open" : "closed"}
      data-disabled={item.disabled ? "" : undefined}
      data-roving-item=""
      disabled={item.disabled}
      {...props}
      id={item.triggerId}
      onClick={composeEventHandlers(onClick, () => {
        if (!item.open) accordion.open(item.value);
        else if (accordion.collapsible) accordion.close(item.value);
      })}
    />
  );
}

function Content({
  forceMount,
  children,
  ...props
}: React.ComponentProps<"div"> & { forceMount?: boolean }) {
  const accordion = useAccordion();
  const item = useItem();
  if (!item.open && !forceMount) return null;
  return (
    <div
      role="region"
      aria-labelledby={item.triggerId}
      data-orientation={accordion.orientation}
      data-state={item.open ? "open" : "closed"}
      data-disabled={item.disabled ? "" : undefined}
      {...props}
      id={item.contentId}
    >
      {children}
    </div>
  );
}

export const Accordion = { Root, Item, Header, Trigger, Content };

"use client";
// ROC primitive: the reading direction set by a DirectionProvider, with no dependencies.
import * as React from "react";

export type Dir = "ltr" | "rtl";

export const DirectionContext = React.createContext<Dir | undefined>(undefined);

/** A `dir` prop wins, then the provider; undefined means "use the CSS direction". */
export function useDirectionContext(local?: Dir): Dir | undefined {
  return local ?? React.useContext(DirectionContext);
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

"use client";
// ROC primitive: arrow-key focus movement and a single tab stop for a group of items.
// Items mark themselves with `data-roving-item`; each group marks its root `data-roving-root`.
import * as React from "react";

export type Orientation = "horizontal" | "vertical";
export const ROVING_ROOT = "data-roving-root";
export const ROVING_ITEM = "[data-roving-item]";

const INTENT: Record<string, "prev" | "next" | "first" | "last"> = {
  ArrowLeft: "prev",
  ArrowUp: "prev",
  ArrowRight: "next",
  ArrowDown: "next",
  PageUp: "first",
  Home: "first",
  PageDown: "last",
  End: "last",
};

/** Items that belong to this group (not to a nested one) and can take focus. */
export function focusableItems(root: HTMLElement) {
  return Array.from(root.querySelectorAll<HTMLElement>(ROVING_ITEM)).filter(
    (item) =>
      item.closest(`[${ROVING_ROOT}]`) === root &&
      !item.matches(":disabled, [data-disabled]"),
  );
}

/** Move focus for an arrow/Home/End key. Returns whether the key was handled. */
export function handleRovingKey(
  event: React.KeyboardEvent,
  root: HTMLElement | null,
  options: { orientation?: Orientation; dir?: "ltr" | "rtl"; loop?: boolean },
) {
  if (!root || event.metaKey || event.ctrlKey || event.altKey || event.shiftKey)
    return false;
  const current = (event.target as HTMLElement).closest<HTMLElement>(ROVING_ITEM);
  if (!current || current.closest(`[${ROVING_ROOT}]`) !== root) return false;
  const rtl = (options.dir ?? getComputedStyle(root).direction) === "rtl";
  let key = event.key;
  if (rtl && key === "ArrowLeft") key = "ArrowRight";
  else if (rtl && key === "ArrowRight") key = "ArrowLeft";
  const { orientation, loop = true } = options;
  if (orientation === "vertical" && (key === "ArrowLeft" || key === "ArrowRight"))
    return false;
  if (orientation === "horizontal" && (key === "ArrowUp" || key === "ArrowDown"))
    return false;
  const intent = INTENT[key];
  if (!intent) return false;
  event.preventDefault();
  const items = focusableItems(root);
  const index = items.indexOf(current);
  let target: HTMLElement | undefined;
  if (intent === "first") target = items[0];
  else if (intent === "last") target = items[items.length - 1];
  else {
    const step = intent === "next" ? 1 : -1;
    const next = index + step;
    target = loop
      ? items[(next + items.length) % items.length]
      : items[next];
  }
  if (target && target !== current) target.focus();
  return true;
}

/**
 * One tab stop per group: the selected item, or the first enabled item when none
 * is selected. Items read `fallback` and compare it to their `data-roving-value`.
 */
export function useRovingTabStop(selectedSelector: string) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const [fallback, setFallback] = React.useState<string | null>(null);
  React.useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    const items = focusableItems(root);
    const next = items.some((item) => item.matches(selectedSelector))
      ? null
      : (items[0]?.dataset.rovingValue ?? null);
    setFallback((previous) => (previous === next ? previous : next));
  });
  return { ref, fallback };
}

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="accordion-item"] {
  border-bottom: 1px solid var(--roc-line, #e4e4e4);
}
.roc-ui[data-slot="accordion-item"]:last-child {
  border-bottom: 0;
}
.roc-ui-accordion-heading {
  margin: 0;
  font: inherit;
}
.roc-ui[data-slot="accordion-trigger"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border: 0;
  background: transparent;
  width: 100%;
  padding: 16px 0;
  text-align: left;
  font-weight: 500;
  cursor: pointer;
}
.roc-ui[data-slot="accordion-trigger"] svg {
  transition: transform var(--roc-motion-fast) var(--roc-motion-ease);
  color: var(--roc-muted, #888);
}
/* Flip through a flat line; non-scaling stroke keeps the weight constant. */
.roc-ui[data-slot="accordion-trigger"] svg path {
  vector-effect: non-scaling-stroke;
}
.roc-ui[data-slot="accordion-trigger"][data-state="open"] svg {
  transform: scaleY(-1);
}
.roc-ui-accordion-layout { overflow: hidden; }
.roc-ui-accordion-clip {
  min-height: 0;
  overflow: hidden;
}
.roc-ui-accordion-body {
  padding: 0 0 18px;
  line-height: 1.65;
  color: var(--roc-muted, #737373);
  transition:
    opacity var(--roc-motion-fast) var(--roc-motion-ease),
    filter var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui-accordion-layout[data-open="false"] .roc-ui-accordion-body {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui[data-slot="accordion-trigger"] svg {
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .roc-ui-accordion-layout,
  .roc-ui-accordion-body {
    transition: none;
  }
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
